-- APPLY-BY: ci
-- DB: qnfo-audit
-- Rollback: DELETE FROM analytics_metric_triggers WHERE metric_key IN ('youtube_videos_30d', 'youtube_spend_usd_month'); DELETE FROM metric_registry WHERE metric IN ('youtube_videos_30d', 'youtube_spend_usd_month'); DELETE FROM fleet_budget WHERE node_class = 'cost:youtube_shorts_month'; DELETE FROM remediation_contracts WHERE class LIKE 'fm-youtube-%'; DELETE FROM failure_modes WHERE fm_key LIKE 'youtube-%'; DROP TABLE IF EXISTS youtube_spend; DROP TABLE IF EXISTS youtube_videos
-- spof-review: one new worker (qnfo-youtube-shorts) with one container class; the single point of failure is the render container, and a failed render keeps its job in R2 (youtube/<id>/job.json) so a GitHub-runner render (python container/render.py job.json out) can finish it; YouTube credentials are Worker secrets only.
-- YT-SERVER-1 (2026-10-27, pillar reach, project YT.SHORTS). Ledger of Shorts, monthly spend ledger, two metrics with triggers, the owner's cost cap as a fleet_budget row.
CREATE TABLE IF NOT EXISTS youtube_videos (id INTEGER PRIMARY KEY AUTOINCREMENT, slug TEXT NOT NULL UNIQUE, rev TEXT, state TEXT NOT NULL, title TEXT, attempts INTEGER NOT NULL DEFAULT 0, note TEXT, duration_s REAL, video_id TEXT, privacy TEXT, synthetic INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, uploaded_at TEXT, views INTEGER);
CREATE TABLE IF NOT EXISTS youtube_spend (id INTEGER PRIMARY KEY AUTOINCREMENT, month TEXT NOT NULL, row_id INTEGER, kind TEXT NOT NULL, units REAL NOT NULL, usd REAL NOT NULL, note TEXT, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_youtube_spend_month ON youtube_spend (month);

INSERT OR IGNORE INTO fleet_budget (node_class, cap, target, current, unit, updated_at) VALUES ('cost:youtube_shorts_month', 50, 45, 0, 'usd_month', datetime('now'));

INSERT OR IGNORE INTO metric_registry (metric, layer, kind, formula, source_of_truth, baseline, target, owner, disposition_actor, refresh_cadence, warning_band, kill_band, state, refresh_class) VALUES
 ('youtube_videos_30d', 'reach', 'leading', 'count(youtube_videos WHERE state = uploaded AND uploaded_at >= now-30d)', 'qnfo-audit.youtube_videos, written by qnfo-youtube-shorts on its hourly tick', 'new 2026-10-27', '>= 4', 'qnfo-youtube-shorts', 'qnfo-youtube-shorts hourly cron (YT-SERVER-1)', 'hourly', '< 4', '< 1', 'UNMEASURED', 'fast'),
 ('youtube_spend_usd_month', 'cost', 'guard', 'sum(youtube_spend.usd) for the current calendar month', 'qnfo-audit.youtube_spend, written by qnfo-youtube-shorts per stage (measured units, list-price rates)', 'new 2026-10-27', '<= 45', 'qnfo-youtube-shorts', 'qnfo-youtube-shorts hard stop at 45 USD (SPEND_STOP_USD); owner cap 50 USD all-in', 'hourly', '> 35', '> 45', 'UNMEASURED', 'fast');

INSERT OR IGNORE INTO analytics_metric_triggers (metric_key, title, source_table, operator, threshold, priority, action, owner, queue_target, cooldown_hours, enabled, notes)
SELECT v.metric_key, v.title, 'meta', v.operator, v.threshold, v.priority, v.action || ' Definition of done: the metric is back inside its target at the next hourly tick; the issue closes on its probe.', 'qnfo-youtube-shorts', 'agent_issues', 24, 1, 'YT-SERVER-1 2026-10-27'
FROM (SELECT 'youtube_videos_30d' AS metric_key, 'YouTube Shorts: fewer than 1 Short uploaded in 30 days' AS title, 'lt' AS operator, 1 AS threshold, 5 AS priority, 'Pillar reach. Read GET https://qnfo-youtube-shorts.q08.workers.dev/status (rows with state, attempts, note) and qnfo-audit.cloud_ops_events job qnfo-youtube-shorts: a stuck rendering row means the container failed (GET /status container.configured must be true; redeploy through deploy-youtube-shorts.yml), awaiting-youtube-credentials means the YT_* secrets are missing or the OAuth app is in Testing mode (7-day refresh tokens), rejected means the director left fewer than 3 supported beats.' AS action
      UNION ALL SELECT 'youtube_spend_usd_month', 'YouTube Shorts: month spend above the 45 USD hard stop', 'gt', 45, 6, 'Pillar cost, owner cap 50 USD a month all-in. The cron already skips new work at 45. Read youtube_spend grouped by kind for the month and compare units with the real bill (Workers AI neurons, Container vCPU-seconds): correct PRICES in qnfo-youtube-shorts/worker.js if the estimate is off, and move the lever (fewer videos a week, a cheaper TTS) rather than raising the cap.') v
WHERE NOT EXISTS (SELECT 1 FROM analytics_metric_triggers x WHERE x.metric_key = v.metric_key AND x.enabled = 1);

UPDATE roadmap_implementation SET status = 'built', artifact_ref = 'qnfo-youtube-shorts', evidence = 'qnfo-youtube-shorts worker, container/ render image, deploy-youtube-shorts.yml; ledger youtube_videos. Live proof: see the youtube_videos row with a video_id' WHERE item = 'YT-3' AND source = 'yt-shorts-2026';
UPDATE roadmap_implementation SET status = 'built', evidence = 'youtube_spend ledger, fleet_budget cost:youtube_shorts_month (cap 50), metrics youtube_spend_usd_month and youtube_videos_30d with triggers, hard stop at 45 USD in the hourly tick' WHERE item = 'YT-4' AND source = 'yt-shorts-2026';
UPDATE roadmap_implementation SET evidence = 'owner directive 2026-10-27: all Shorts public by default (supersedes private-until-reviewed); views and average view duration per Short still to be read back into youtube_videos.views' WHERE item = 'YT-6' AND source = 'yt-shorts-2026';

INSERT OR IGNORE INTO failure_modes (fm_key, failure_mode, root_cause, remediation, detector, probe_class, first_seen, issue_id, trigger_condition, symptom, blast_radius) VALUES
('youtube-render-stuck','a Short never leaves the render stage because the Cloudflare Container is not attached, was evicted or fails the job','the container is a single path: a deploy that drops [[containers]] (the qnfo-containers-pilot incident, issue 1485) or an evicted instance loses the render, and the worker would otherwise retry the same path forever','YT-FM-RENDER-1: after two failed attempts the row becomes runner_pending (it no longer blocks new papers) and its job stays in R2 for youtube-render-runner.yml; deploy-youtube-shorts.yml fails when /status shows container.configured false','worker.js moves a twice-failed render to runner_pending','fm-youtube-render-stuck','2026-10-27',NULL,'a render attempt errors or the container does not answer /health','youtube_videos row sits in audio or rendering, youtube_videos_30d stays at 0','one Short at a time; the queue behind it is not blocked'),
('youtube-spend-overrun','the pipeline adds more than the owner cap of USD 50 a month','list-price rates are estimates and a retry loop multiplies the TTS and container seconds','youtube_spend ledger per stage with measured units; the hourly tick stops new work at SPEND_STOP_USD (45); metric youtube_spend_usd_month with a trigger above 45','worker.js hard stop','fm-youtube-spend-overrun','2026-10-27',NULL,'month spend reaches 45 USD','no new Short is started until the month turns','the pipeline only'),
('youtube-unsupported-claim','a published Short states a number or claim that the plain-language article does not contain','an LLM director invents or rounds figures; correlated model errors pass a single checker','validateBeats drops any beat with a number not in the article body, a second model family (gpt-oss) drops beats with unsupported claims, and fewer than 3 supported beats rejects the paper','worker.js validateBeats','fm-youtube-unsupported-claim','2026-10-27',NULL,'the director writes a beat with a figure absent from the article','a public Short with a wrong figure','the QNFO channel and its credibility'),
('youtube-credentials-lapse','uploads stop because the Google OAuth refresh token expired or the YT_* secrets are absent','an OAuth app in Testing mode issues refresh tokens that expire after 7 days','rendered videos wait in R2 with the note awaiting-youtube-credentials (nothing is lost) and metric youtube_videos_30d breaches; the app is set to In production before the token is stored','worker.js awaiting-youtube-credentials state','fm-youtube-credentials-lapse','2026-10-27',NULL,'accessToken refresh returns invalid_grant','rows stay rendered, no uploads','the pipeline only'),
('youtube-duplicate-upload','the same paper is uploaded twice','the upload succeeds but the ledger write fails, so the next tick sees an unfinished row','youtube_videos.slug is UNIQUE, the ledger write retries three times and logs youtube.ledger_retry with the video id','worker.js ledger retry','fm-youtube-duplicate-upload','2026-10-27',NULL,'a D1 write error right after videos.insert','two public videos of one paper','one paper');

INSERT OR IGNORE INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, module, budget_ms, max_items, requires_container) VALUES
('fm-youtube-render-stuck',NULL,'YT-SERVER-1','failure-mode detector: qnfo-youtube-shorts carries the guard','{"paths": ["qnfo-youtube-shorts/worker.js"], "contains": "runner_pending"}','code-read',3,'qnfo-fleet-control',1,'active','failure-mode',45000,5,0),
('fm-youtube-spend-overrun',NULL,'YT-SERVER-1','failure-mode detector: qnfo-youtube-shorts carries the guard','{"paths": ["qnfo-youtube-shorts/worker.js"], "contains": "SPEND_STOP_USD"}','code-read',3,'qnfo-fleet-control',1,'active','failure-mode',45000,5,0),
('fm-youtube-unsupported-claim',NULL,'YT-SERVER-1','failure-mode detector: qnfo-youtube-shorts carries the guard','{"paths": ["qnfo-youtube-shorts/worker.js"], "contains": "number-not-in-article"}','code-read',3,'qnfo-fleet-control',1,'active','failure-mode',45000,5,0),
('fm-youtube-credentials-lapse',NULL,'YT-SERVER-1','failure-mode detector: qnfo-youtube-shorts carries the guard','{"paths": ["qnfo-youtube-shorts/worker.js"], "contains": "awaiting-youtube-credentials"}','code-read',3,'qnfo-fleet-control',1,'active','failure-mode',45000,5,0),
('fm-youtube-duplicate-upload',NULL,'YT-SERVER-1','failure-mode detector: qnfo-youtube-shorts carries the guard','{"paths": ["qnfo-youtube-shorts/worker.js"], "contains": "youtube.ledger_retry"}','code-read',3,'qnfo-fleet-control',1,'active','failure-mode',45000,5,0);
